-- Enable core extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pg_stat_statements";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";

-- Sample ecommerce events table
CREATE TABLE events (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id BIGINT NOT NULL,
    event_type VARCHAR(50) NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Create GIN index on JSONB payload for fast key-value containment queries
CREATE INDEX idx_events_payload ON events USING gin (payload);

-- 00: Server Information & Process Inspection
SELECT version();
SELECT name, setting, unit, short_desc FROM pg_settings WHERE name IN ('shared_buffers', 'work_mem', 'max_connections');

-- 01: JSONB Queries
INSERT INTO events (user_id, event_type, payload) VALUES
(1001, 'ORDER_COMPLETED', '{"order_id": "ord_123", "total": 99.50, "items": ["book", "pen"]}'::jsonb);

-- Extract scalar field as text (->>)
SELECT payload->>'order_id' AS order_id, payload->>'total' AS total FROM events;

-- JSONB Containment Query (@> utilizes GIN index!)
SELECT * FROM events WHERE payload @> '{"order_id": "ord_123"}';

-- Inspect dead tuples across user tables
SELECT relname, n_live_tup, n_dead_tup, last_vacuum, last_autovacuum
FROM pg_stat_user_tables;

-- 1. Partial Index (Indexes only active records, 10x smaller)
CREATE INDEX idx_active_users ON events (user_id) WHERE event_type = 'ORDER_COMPLETED';

-- 2. Expression / Functional Index
CREATE INDEX idx_lower_event_type ON events (LOWER(event_type));

-- Explain Query with memory buffer hit analysis
EXPLAIN (ANALYZE, BUFFERS, VERBOSE)
SELECT * FROM events WHERE user_id = 1001;

-- Range-partitioned table by month
CREATE TABLE measurement (
    city_id int not null,
    logdate date not null,
    peaktemp int
) PARTITION BY RANGE (logdate);

CREATE TABLE measurement_y2026m08 PARTITION OF measurement
    FOR VALUES FROM ('2026-08-01') TO ('2026-09-01');

CREATE OR REPLACE FUNCTION get_user_event_count(p_user_id BIGINT)
RETURNS BIGINT AS $$
DECLARE
    v_count BIGINT;
BEGIN
    SELECT COUNT(*) INTO v_count FROM events WHERE user_id = p_user_id;
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

-- Enable RLS on events table
ALTER TABLE events ENABLE ROW LEVEL SECURITY;

-- Create Policy isolating tenant data
CREATE POLICY tenant_isolation_policy ON events
FOR ALL
USING (user_id = current_setting('app.current_user_id')::bigint);

-- High-performance job queue pattern with SKIP LOCKED
BEGIN;
SELECT id FROM events 
WHERE event_type = 'PENDING'
ORDER BY created_at
LIMIT 1
FOR UPDATE SKIP LOCKED;
-- Process job...
COMMIT;
